<script type="text/javascript">
function callFuncLoadMeta(){
    jQuery.ajax({
        type:'POST',
        url: '<?php echo url_for('subserie/searchMetadatos'); ?>',
        data: jQuery.param({ subserie_id: jQuery("#subserie_id").val()}) ,
        contentType: 'application/x-www-form-urlencoded; charset=UTF-8',
        cache:false,
        processData: false,
        beforeSend: function() {
        },
        success:function(data){
            try {
                if(data == null || data == '') {
                    jQuery(".dinamicallfields").remove();
                }else{
                    jQuery("#structmetadatos").after(data);
                    applyDatePicker()
                }
            }catch(err) {
                //toastr.error(err.message);
            }
        },
        complete: function(){
            //toastr.info('Por favor actualice esta pagina para ver los cambios'); 
        },
    });
}

function applyDatePicker(){
  jQuery(".datepicker").each(function(i, el){
    var $this = jQuery(el),
      opts = {
        format: attrDefault($this, 'format', 'mm/dd/yyyy'),
        startDate: attrDefault($this, 'startDate', ''),
        endDate: attrDefault($this, 'endDate', ''),
        daysOfWeekDisabled: attrDefault($this, 'disabledDays', ''),
        startView: attrDefault($this, 'startView', 0),
        autoclose: true,
        language: 'es',
        rtl: rtl()
      },
      $n = $this.next(),
      $p = $this.prev();

    $this.datepicker(opts);

    if($n.is('.input-group-addon') && $n.has('a'))
    {
      $n.on('click', function(ev)
      {
        ev.preventDefault();

        $this.datepicker('show');
      });
    }

    if($p.is('.input-group-addon') && $p.has('a'))
    {
      $p.on('click', function(ev)
      {
        ev.preventDefault();

        $this.datepicker('show');
      });
    }
  });  
}
</script>